import zipfile
import re
import xml.etree.ElementTree as ET

NS = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
RNS = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'


def col_number(ref):
    letters = re.match(r'[A-Z]+', ref).group(0)
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch) - 64)
    return n - 1


with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()

    shared = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall(f'{NS}si'):
            shared.append(''.join(t.text or '' for t in si.iter(f'{NS}t')))

    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {r.get('Id'): r.get('Target') for r in rels_root}

    sheets = []
    for s in wb_root.iter(f'{NS}sheet'):
        name = s.get('name')
        target = rel_map.get(s.get(f'{RNS}id'), '').lstrip('/')
        if not target.startswith('xl/'):
            target = 'xl/' + target
        sheets.append((name, target))

    print('Sheets:', [n for n, _ in sheets])


    def cell_value(c):
        t = c.get('t')
        v = c.find(f'{NS}v')
        if t == 's' and v is not None:
            return shared[int(v.text)]
        if t == 'inlineStr':
            is_el = c.find(f'{NS}is')
            if is_el is None:
                return None
            return ''.join(tt.text or '' for tt in is_el.iter(f'{NS}t'))
        if v is None:
            return None
        text = v.text
        try:
            if '.' in text or 'E' in text.upper():
                return float(text)
            return int(text)
        except ValueError:
            return text


    AMT_KEYS = ('amount', 'cost', 'expense', 'total', 'price', 'value')
    CAT_KEYS = ('category', 'item', 'name', 'description')

    grand_total = 0.0
    for sheet_name, target in sheets:
        print(f'\n=== Sheet: {sheet_name} ===')
        root = ET.fromstring(z.read(target))
        sheet_data = root.find(f'{NS}sheetData')
        grid = []
        for row in sheet_data.findall(f'{NS}row'):
            cells = {}
            for c in row.findall(f'{NS}c'):
                val = cell_value(c)
                if val is not None:
                    cells[col_number(c.get('r'))] = val
            grid.append(cells)

        header_idx = None
        amt_cols = []
        for r_idx, cells in enumerate(grid):
            joined = ' '.join(str(x).lower() for x in cells.values())
            if any(k in joined for k in AMT_KEYS) and any(k in joined for k in CAT_KEYS):
                header_idx = r_idx
                amt_cols = [ci for ci, x in cells.items()
                            if any(k in str(x).lower() for k in AMT_KEYS)]
                print(f'Header row {r_idx + 1}: {cells} | amount cols: {amt_cols}')
                break

        for r_idx, cells in enumerate(grid, 1):
            if cells:
                print(f'Row {r_idx}: {cells}')

        if header_idx is not None:
            for cells in grid[header_idx + 1:]:
                for ci in amt_cols:
                    if ci in cells and isinstance(cells[ci], (int, float)):
                        grand_total += cells[ci]

    print(f'\nTOTAL EXPENSES (heuristic sum): {grand_total}')

