import zipfile
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_to_idx(ref):
    letters = ''.join(ch for ch in ref if ch.isalpha())
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch.upper()) - 64)
    return idx - 1

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("ZIP CONTENTS:", names)

    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))

    rid_to_target = {}
    for rel in rels_root:
        rid_to_target[rel.attrib.get('Id')] = rel.attrib.get('Target')

    shared = []
    if 'xl/sharedStrings.xml' in names:
        ss_root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss_root.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    def cell_value(c):
        t = c.attrib.get('t')
        v = c.find('m:v', NS)
        raw = v.text if v is not None else None
        if t == 's' and raw is not None:
            return shared[int(raw)]
        if t == 'inlineStr':
            return ''.join(t.text or '' for t in c.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        if t == 'b':
            return raw == '1'
        if raw is None:
            return None
        try:
            return float(raw)
        except ValueError:
            return raw

    sheets = []
    for sheet in wb_root.findall('.//m:sheets/m:sheet', NS):
        name = sheet.attrib.get('name')
        rid = sheet.attrib.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        target = rid_to_target.get(rid)
        sheets.append((name, target))

    for name, target in sheets:
        path = 'xl/' + target.lstrip('/')
        print(f"\n=== Sheet: {name} ({path}) ===")
        root = ET.fromstring(z.read(path))
        for row in root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
            for c in row:
                if c.tag.endswith('}c'):
                    val = cell_value(c)
                    if val is not None:
                        print(f"{c.attrib.get('r')}: {val!r}")

