            return ''.join(tt.text or '' for tt in is_el.iter(f'{NS}t'))
        if t == 'str' and v is not None:
            return v.text
        if v is None or v.text is None:
            return None
        text = v.text
        try:
            if '.' in text or 'E' in text.upper():
                return float(text)
            return int(text)
        except ValueError:
            return text


    grid = []
