            val = cell_value(c)
            if val is not None:
                cells[col_number(c.get('r'))] = val
        grid.append(cells)

    # Locate the EXPENSES section and the Total Expenses row
    start = None
    end = None
    for i, cells in enumerate(grid):
        label = str(cells.get(0, '')).strip().upper()
        if label == 'EXPENSES':
            start = i + 1
        if label == 'TOTAL EXPENSES':
            end = i
            break

    cat_totals = OrderedDict()
    overall = 0.0
    print(f'Expense rows {start + 1}..{end} (1-based):')
    for cells in grid[start:end]:
